"""
title: Bayan al-Sunnah: Islamic Topics & Introductory Evidence Tool
author: Hadith Project
version: 1.2.0
description: Read-only access to six reviewed introductory Islamic topics, scriptural evidence occurrences, and audience-tailored lesson formats with strict contract validation.
"""

import os
import json
import hashlib
from typing import Dict, Any, List, Optional
from pathlib import Path
from pydantic import BaseModel, Field

try:
    from tools.hadith_contract_helper import build_response, to_json_str
except ImportError:
    try:
        from hadith_contract_helper import build_response, to_json_str
    except ImportError:
        from datetime import datetime, timezone
        def build_response(status, data=None, evidence=None, coverage=None, warnings=None, dataset_version="2026-10-06-v1.1", retrieved_at=None):
            return {
                "schema_version": "1",
                "status": status,
                "data": data or {},
                "evidence": evidence or {},
                "coverage": coverage or {},
                "warnings": warnings or [],
                "dataset_version": dataset_version,
                "retrieved_at": retrieved_at or datetime.now(timezone.utc).isoformat()
            }
        def to_json_str(payload, indent=2):
            return json.dumps(payload, ensure_ascii=False, indent=indent)


class Tools:
    @staticmethod
    def _source_locator(occ: Dict[str, Any]) -> Dict[str, Any]:
        """Keep dataset positions separate from numbers mentioned in attributed rulings."""
        position = occ.get("source_position")
        label = (f"موضع المصدر المحلي: {position}" if position is not None
                 else "موضع المصدر المحلي: غير متاح في المصدر المسترجع")
        return {
            "numbering_system": "itqan_local_position",
            "source_position": position,
            "source_entry_id": occ.get("source_entry_id"),
            "source_url": occ.get("source_url"),
            "display_label": label,
            "numbering_note": "هذا موضع السجل في بيانات إتقان، وليس رقم الحديث في جميع الطبعات. أرقام attributed_judgment إحالات مستقلة ولا تحل محله."
        }

    @classmethod
    def _source_citation(cls, occ: Dict[str, Any]) -> str:
        return (f"{occ['collection'].title()} — {occ['chapter_title']} — "
                f"{cls._source_locator(occ)['display_label']} ({occ['occurrence_id']})")

    @staticmethod
    def _verify_json_file(path: str) -> bool:
        if not path or not os.path.exists(path):
            return False
        try:
            if os.path.getsize(path) == 0:
                return False
            with open(path, "r", encoding="utf-8") as f:
                data = json.load(f)
            return bool(data)
        except Exception:
            return False

    @classmethod
    def _resolve_candidate_path(cls, env_var: str, current_val: str, candidates: List[str]) -> str:
        env_val = os.environ.get(env_var)
        if env_val:
            env_val = os.path.abspath(env_val)
            if cls._verify_json_file(env_val):
                return env_val

        if current_val:
            cur_abs = os.path.abspath(current_val) if not current_val.startswith("c:\\") or os.name == 'nt' else current_val
            if os.path.exists(cur_abs) and cls._verify_json_file(cur_abs):
                return cur_abs

        search_roots = [
            "/app/backend/data",
            "/app/data",
            "/data",
            "/root/open-webui",
            "/root/open-webui/hadith",
            "/root",
            os.getcwd(),
            os.path.abspath(os.path.join(os.getcwd(), "..")),
            os.path.abspath(os.path.join(os.getcwd(), "../..")),
            os.path.abspath(os.path.join(os.getcwd(), "hadith")),
            os.path.abspath(os.path.join(os.getcwd(), "open-webui")),
            os.path.abspath(os.path.join(os.getcwd(), "open-webui/hadith")),
        ]
        if "__file__" in globals():
            tool_dir = os.path.dirname(os.path.abspath(__file__))
            search_roots.extend([
                tool_dir,
                os.path.abspath(os.path.join(tool_dir, "..")),
                os.path.abspath(os.path.join(tool_dir, "../..")),
                os.path.abspath(os.path.join(tool_dir, "../../..")),
            ])
        if os.name == 'nt':
            search_roots.append(r"c:\Users\mhdal\OneDrive\AI\Hadith KSA")

        for c in candidates:
            if os.path.isabs(c) and cls._verify_json_file(c):
                return os.path.abspath(c)
            for root in search_roots:
                p = os.path.abspath(os.path.join(root, c))
                if cls._verify_json_file(p):
                    return p
        return current_val or ""

    class Valves(BaseModel):
        TAXONOMY_PATH: str = Field(
            default="",
            description="Absolute path to the topic taxonomy JSON (or set HADITH_TAXONOMY_PATH)."
        )
        LESSON_PACKS_PATH: str = Field(
            default="",
            description="Absolute path to the reviewed lesson packs JSON (or set HADITH_LESSON_PACKS_PATH)."
        )

        def __init__(self, **data):
            super().__init__(**data)
            self._ensure_resolved()

        def _ensure_resolved(self):
            if not self.TAXONOMY_PATH or not Tools._verify_json_file(self.TAXONOMY_PATH):
                self.TAXONOMY_PATH = Tools._resolve_candidate_path(
                    "HADITH_TAXONOMY_PATH",
                    self.TAXONOMY_PATH,
                    [
                        "planning/islam_topic_taxonomy_v1.json",
                        "hadith/planning/islam_topic_taxonomy_v1.json",
                        "open-webui/hadith/planning/islam_topic_taxonomy_v1.json",
                        "backend/data/islam_topic_taxonomy_v1.json",
                        "islam_topic_taxonomy_v1.json"
                    ]
                )
            if not self.LESSON_PACKS_PATH or not Tools._verify_json_file(self.LESSON_PACKS_PATH):
                self.LESSON_PACKS_PATH = Tools._resolve_candidate_path(
                    "HADITH_LESSON_PACKS_PATH",
                    self.LESSON_PACKS_PATH,
                    [
                        "planning/bayan_lesson_packs_v1.json",
                        "hadith/planning/bayan_lesson_packs_v1.json",
                        "open-webui/hadith/planning/bayan_lesson_packs_v1.json",
                        "backend/data/bayan_lesson_packs_v1.json",
                        "bayan_lesson_packs_v1.json"
                    ]
                )

    def _ensure_taxonomy(self) -> str:
        if not self._verify_json_file(self.valves.TAXONOMY_PATH):
            self.valves.TAXONOMY_PATH = self._resolve_candidate_path(
                "HADITH_TAXONOMY_PATH",
                self.valves.TAXONOMY_PATH,
                [
                    "planning/islam_topic_taxonomy_v1.json",
                    "hadith/planning/islam_topic_taxonomy_v1.json",
                    "open-webui/hadith/planning/islam_topic_taxonomy_v1.json",
                    "backend/data/islam_topic_taxonomy_v1.json",
                    "islam_topic_taxonomy_v1.json"
                ]
            )
        return self.valves.TAXONOMY_PATH

    def _ensure_lesson_packs(self) -> str:
        if not self._verify_json_file(self.valves.LESSON_PACKS_PATH):
            self.valves.LESSON_PACKS_PATH = self._resolve_candidate_path(
                "HADITH_LESSON_PACKS_PATH",
                self.valves.LESSON_PACKS_PATH,
                [
                    "planning/bayan_lesson_packs_v1.json",
                    "hadith/planning/bayan_lesson_packs_v1.json",
                    "open-webui/hadith/planning/bayan_lesson_packs_v1.json",
                    "backend/data/bayan_lesson_packs_v1.json",
                    "bayan_lesson_packs_v1.json"
                ]
            )
        return self.valves.LESSON_PACKS_PATH

    def _resolve_all_paths(self):
        self._ensure_taxonomy()
        self._ensure_lesson_packs()

    def __init__(self):
        self.valves = self.Valves()
        self._resolve_all_paths()
        self._taxonomy_cache = None
        self._lesson_packs_cache = None

    def _load_data(self):
        self._resolve_all_paths()
        if not self._taxonomy_cache and self._verify_json_file(self.valves.TAXONOMY_PATH):
            try:
                with open(self.valves.TAXONOMY_PATH, "r", encoding="utf-8") as f:
                    self._taxonomy_cache = json.load(f)
            except Exception:
                pass

        if not self._lesson_packs_cache and self._verify_json_file(self.valves.LESSON_PACKS_PATH):
            try:
                with open(self.valves.LESSON_PACKS_PATH, "r", encoding="utf-8") as f:
                    self._lesson_packs_cache = json.load(f)
            except Exception:
                pass

    def list_islam_topics(self) -> str:
        """
        List the six introductory topics for introducing Islam with core questions and coverage.

        :return: Standardized JSON envelope containing topic metadata, questions, and subtopics.
        """
        self._load_data()
        if not self._taxonomy_cache:
            return to_json_str(build_response(
                status="unavailable",
                warnings=["Taxonomy database file not found or inaccessible."]
            ))

        topics_summary = []
        for t in self._taxonomy_cache.get("topics", []):
            topics_summary.append({
                "topic_id": t["id"],
                "title_ar": t["title_ar"],
                "title_en": t["title_en"],
                "initial_question_ar": t["initial_question_ar"],
                "subtopics_count": len(t.get("subtopics", [])),
                "subtopics": [{**st, "card_available": st["id"] in next((p.get("subtopic_cards", {}) for p in (self._lesson_packs_cache or {}).get("topics", []) if p["topic_id"] == t["id"]), {})} for st in t.get("subtopics", [])]
            })

        return to_json_str(build_response(
            status="ok",
            data={
                "track": "Bayan al-Sunnah — Introduction to Islam",
                "topics_count": len(topics_summary),
                "topics": topics_summary
            },
            coverage={
                "curated_topics_count": len(topics_summary),
                "status": "curated_taxonomy_draft",
                "review_state": "pending_external_scholarly_signoff"
            }
        ))

    def get_topic_evidence(self, topic_id: str, audience: str = "newcomer", language: str = "ar") -> str:
        """
        Retrieve vetted scriptural Hadith evidence occurrences, attributed rulings, and vocabulary for a topic.

        :param topic_id: Unique topic ID: 'topic-faith', 'topic-mercy', 'topic-worship', 'topic-family', 'topic-fairness', 'topic-knowledge'.
        :param audience: Target audience: 'newcomer' (interested seeker), 'new_muslim' (newly practicing), 'educator' (teacher/mentor).
        :param language: Output language ('ar'). Other languages return status: unavailable until reviewed.
        :return: Standardized JSON envelope with verified occurrences, learning objectives, vocabulary, and sources.
        """
        # Validate language availability
        clean_lang = language.lower().strip()
        if clean_lang != "ar":
            return to_json_str(build_response(
                status="unavailable",
                data={"requested_language": language, "available_languages": ["ar"]},
                warnings=[f"اللغة '{language}' غير متاحة حالياً؛ الترجمات المعتمدة قيد الإعداد والمراجعة. المحتوى متوفر بالعربية فقط."]
            ))

        self._load_data()
        if not self._lesson_packs_cache:
            return to_json_str(build_response(
                status="unavailable",
                warnings=["Lesson packs data file not found or inaccessible."]
            ))

        clean_topic_id = topic_id.lower().strip()
        matched_topic = None
        for t in self._lesson_packs_cache.get("topics", []):
            if t["topic_id"] == clean_topic_id:
                matched_topic = t
                break

        if not matched_topic:
            valid_ids = [t["topic_id"] for t in self._lesson_packs_cache.get("topics", [])]
            return to_json_str(build_response(
                status="invalid_reference",
                data={"requested_topic_id": topic_id, "valid_topic_ids": valid_ids},
                warnings=[f"المعرف المطلوب '{topic_id}' غير صالح. المعرفات المعتمدة هي: {', '.join(valid_ids)}"]
            ))

        clean_audience = audience.lower().strip()
        if clean_audience not in ["newcomer", "new_muslim", "educator"]:
            clean_audience = "newcomer"

        learning_objective = matched_topic["learning_objectives"].get(clean_audience, matched_topic["learning_objectives"]["newcomer"])

        evidence_occurrences = []
        occurrence_ids = []
        explanation_ids = []
        claim_evidence = []
        collections_found = set()

        for occ in matched_topic.get("occurrences", []):
            occ_id = occ["occurrence_id"]
            occurrence_ids.append(occ_id)
            collections_found.add(occ["collection"])
            exp_id = occ.get("explanation_reference", {}).get("provider_id")
            if exp_id:
                explanation_ids.append(exp_id)

            claim_evidence.append({
                "passage_id": occ.get("passage_id"),
                "occurrence_id": occ_id,
                "established_principle": occ.get("selection_rationale", ""),
                "attributed_judgment": occ.get("attributed_judgment", "")
            })

            evidence_occurrences.append({
                "occurrence_id": occ_id,
                "source_position": occ.get("source_position"),
                "source_entry_id": occ.get("source_entry_id"),
                "source_locator": self._source_locator(occ),
                "source_citation": self._source_citation(occ),
                "passage_id": occ.get("passage_id"),
                "collection": occ["collection"],
                "chapter_title": occ["chapter_title"],
                "arabic_text": occ["arabic_text"],
                "text_sha256": occ["text_sha256"],
                "source_url": occ["source_url"],
                "attributed_judgment": occ["attributed_judgment"],
                "exact_quote": occ.get("exact_quote", {}),
                "explanation_reference": occ.get("explanation_reference", {}),
                "vocabulary": occ.get("vocabulary", []),
                "selection_rationale": occ.get("selection_rationale", "")
            })

        return to_json_str(build_response(
            status="ok",
            data={
                "topic_id": matched_topic["topic_id"],
                "title_ar": matched_topic["title_ar"],
                "title_en": matched_topic["title_en"],
                "initial_question": matched_topic["initial_question"],
                "audience": clean_audience,
                "learning_objective": learning_objective,
                "occurrence_ids": occurrence_ids,
                "explanation_ids": explanation_ids,
                "occurrences": evidence_occurrences,
                "claim_evidence": claim_evidence,
                "review_status": "needs_review",
                "source_verified": True,
                "scholarly_approved": False,
                "reviewer": None,
                "limitations": "مسودة أدلة منتقاة برمجياً قيد المراجعة والاعتماد العلمي المتخصص."
            },
            coverage={
                "actual_collections_in_pack": sorted(list(collections_found)),
                "occurrences_retrieved": len(evidence_occurrences),
                "honest_coverage_note": f"الشواهد مستخرجة من مجموعات: {', '.join(sorted(list(collections_found)))}; ولا يُزعم استيعاب الكتب الستة بأكملها."
            }
        ))

    def get_reviewed_lesson(self, topic_id: str, audience: str = "newcomer", format: str = "card", language: str = "ar", subtopic_id: str = "") -> str:
        """
        Retrieve audience-tailored educational lesson content: 'card' (short card), 'qa' (Q&A), or 'two_minute' (narrative).

        :param topic_id: Unique topic ID: 'topic-faith', 'topic-mercy', 'topic-worship', 'topic-family', 'topic-fairness', 'topic-knowledge'.
        :param audience: Target audience: 'newcomer', 'new_muslim', or 'educator'. Default: 'newcomer'.
        :param subtopic_id: Optional taxonomy subtopic ID. Only explicitly mapped short cards are available; no silent fallback to the parent lesson.
        :param format: Output format: 'card', 'qa', or 'two_minute'. Default: 'card'.
        :param language: Output language ('ar'). Other languages return status: unavailable until reviewed.
        :return: Standardized JSON envelope with discrete quotes, takeaway, citations, and review status.
        """
        # Validate language availability
        clean_lang = language.lower().strip()
        if clean_lang != "ar":
            return to_json_str(build_response(
                status="unavailable",
                data={"requested_language": language, "available_languages": ["ar"]},
                warnings=[f"اللغة '{language}' غير متاحة حالياً؛ الترجمات المعتمدة قيد الإعداد والمراجعة. المحتوى متوفر بالعربية فقط."]
            ))

        self._load_data()
        if not self._lesson_packs_cache:
            return to_json_str(build_response(
                status="unavailable",
                warnings=["Lesson packs data file not found or inaccessible."]
            ))

        clean_topic_id = topic_id.lower().strip()
        matched_topic = None
        for t in self._lesson_packs_cache.get("topics", []):
            if t["topic_id"] == clean_topic_id:
                matched_topic = t
                break

        if not matched_topic:
            valid_ids = [t["topic_id"] for t in self._lesson_packs_cache.get("topics", [])]
            return to_json_str(build_response(
                status="invalid_reference",
                data={"requested_topic_id": topic_id, "valid_topic_ids": valid_ids},
                warnings=[f"المعرف المطلوب '{topic_id}' غير صالح. المعرفات المعتمدة هي: {', '.join(valid_ids)}"]
            ))

        clean_audience = (audience or "").lower().strip()
        clean_format = (format or "").lower().strip()
        valid_audiences = ["newcomer", "new_muslim", "educator"]
        valid_formats = ["card", "qa", "two_minute"]

        if clean_audience not in valid_audiences or clean_format not in valid_formats:
            return to_json_str(build_response(
                status="invalid_reference",
                data={
                    "topic_id": topic_id,
                    "audience": audience,
                    "format": format,
                    "valid_audiences": valid_audiences,
                    "valid_formats": valid_formats
                },
                warnings=[f"الجمهور '{audience}' أو القالب '{format}' غير مدعوم. القيم المعتمدة للجمهور: {valid_audiences}، وللقوالب: {valid_formats}."]
            ))

        learning_objective = matched_topic["learning_objectives"].get(clean_audience, matched_topic["learning_objectives"].get("newcomer", ""))
        lesson_formats = matched_topic.get("lesson_formats", {})
        format_dict = lesson_formats.get(clean_format, {})
        if isinstance(format_dict, dict) and clean_audience in format_dict:
            format_content = format_dict[clean_audience]
        else:
            format_content = format_dict

        clean_subtopic = subtopic_id.strip().lower()
        selected_occurrences = matched_topic.get("occurrences", [])
        subtopic = None
        if clean_subtopic:
            tax_topic = next((t for t in (self._taxonomy_cache or {}).get("topics", []) if t["id"] == clean_topic_id), {})
            subtopic = next((s for s in tax_topic.get("subtopics", []) if s["id"] == clean_subtopic), None)
            scoped = matched_topic.get("subtopic_cards", {}).get(clean_subtopic)
            if not subtopic:
                return to_json_str(build_response(status="invalid_reference", data={"topic_id": clean_topic_id, "subtopic_id": clean_subtopic}, warnings=["المحور الفرعي لا ينتمي إلى هذا الموضوع."]))
            if not scoped or clean_format != "card":
                return to_json_str(build_response(status="unavailable", data={"topic_id": clean_topic_id, "subtopic_id": clean_subtopic, "available_formats": ["card"] if scoped else []}, warnings=["لم تُجهز مادة بهذه الصيغة لهذا المحور بعد؛ لا نستبدلها بالدرس العام دون اختيارك."]))
            wanted = set(scoped["passage_ids"])
            selected_occurrences = [o for o in selected_occurrences if o.get("passage_id") in wanted]
            learning_objective = scoped["learning_objective"]
            format_content = {**format_content, "headline": scoped["headline"], "takeaway": scoped["takeaway"], "quotes": [q for q in format_content.get("quotes", []) if q.get("passage_id") in wanted]}

        occurrence_ids = [occ["occurrence_id"] for occ in selected_occurrences]
        citations = [self._source_citation(occ) for occ in selected_occurrences]

        quotes = []
        if clean_format == "card":
            quotes = [dict(q) for q in format_content.get("quotes", [])]
        else:
            for occ in selected_occurrences:
                quotes.append({
                    "occurrence_id": occ["occurrence_id"],
                    "passage_id": occ.get("passage_id"),
                    "text": f"«{occ.get('exact_quote', {}).get('arabic', '')}»",
                    "source_span": occ.get("exact_quote", {}).get("source_span", [0, 0]),
                    "citation": f"{occ['collection'].title()} — {occ['chapter_title']}"
                })

        by_id = {occ["occurrence_id"]: occ for occ in selected_occurrences}
        for quote in quotes:
            occurrence = by_id.get(quote.get("occurrence_id"))
            if occurrence is not None:
                quote["source_locator"] = self._source_locator(occurrence)
                quote["citation"] = self._source_citation(occurrence)
        # Do not mutate the cached pack, including its audience-specific card data.
        if clean_format == "card":
            format_content = {**format_content, "quotes": quotes}

        presentation = None
        if clean_format == "card":
            names = {"bukhari": "صحيح البخاري", "muslim": "صحيح مسلم", "tirmidhi": "جامع الترمذي", "abudawud": "سنن أبي داود", "nasai": "سنن النسائي", "ibnmajah": "سنن ابن ماجه"}
            visual_quotes = []
            for q in quotes:
                o = by_id.get(q.get("occurrence_id"))
                exact = q.get("exact_text") or (o or {}).get("exact_quote", {}).get("arabic", "")
                span = q.get("source_span", [])
                raw = (o or {}).get("arabic_text", "")
                if not o or len(span) != 2 or not all(isinstance(x, int) for x in span) or not (0 <= span[0] < span[1] <= len(raw)) or raw[span[0]:span[1]] != exact or hashlib.sha256(raw.encode()).hexdigest() != o.get("text_sha256"):
                    return to_json_str(build_response(status="unavailable", warnings=["تعذر التحقق الحرفي من شاهد البطاقة؛ لم يتم إنشاء بطاقة غير موثقة."]))
                visual_quotes.append({"exact_text": exact, "source_label": names.get(o["collection"], o["collection"]) + " · " + o["chapter_title"], "occurrence_id": o["occurrence_id"], "source_url": o["source_url"], "source_span": span, "text_sha256": o["text_sha256"], "source_locator": self._source_locator(o), "attributed_judgment": o.get("attributed_judgment"), "selection_rationale": o.get("selection_rationale", "")})
            if not visual_quotes:
                return to_json_str(build_response(status="unavailable", warnings=["لا تتوفر شواهد قابلة للتحقق لهذه البطاقة."]))
            presentation = {"schema_version": "1", "type": "hadith_card", "headline": format_content["headline"], "takeaway": format_content["takeaway"], "quotes": visual_quotes, "source_details_collapsed": True, "review_status": "needs_review"}

        collections_found = set(occ["collection"] for occ in selected_occurrences)

        return to_json_str(build_response(
            status="needs_review",
            data={
                "topic_id": matched_topic["topic_id"],
                "lesson_id": f"lesson-{matched_topic['topic_id']}-{clean_audience}-{clean_format}",
                "title_ar": matched_topic["title_ar"],
                "audience": clean_audience,
                "learning_objective": learning_objective,
                "format": clean_format,
                "lesson_content": format_content,
                "presentation": presentation,
                "subtopic_id": clean_subtopic or None,
                "subtopic_title": subtopic["title_ar"] if subtopic else None,
                "scope_note": scoped["scope_note"] if clean_subtopic else "هذه شواهد منتقاة للموضوع، وليست حصرًا لجميع أحاديثه.",
                "quotes": quotes,
                "occurrence_ids": occurrence_ids,
                "citations": citations,
                "negative_exclusion_note": matched_topic.get("negative_exclusion_record", {}).get("reason", ""),
                "review_status": "needs_review",
                "source_verified": True,
